def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    count = 0.0
    sphere = 0.0
    for t in sites:
        w = max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0)
        count += w
        r = (props.get(t.get('element')) or {}).get('covalent_radius_A')
        if r is not None and isfinite(r) and r > 0:
            sphere += w * r ** 3
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        v = s.get('volume_per_atom_A3')
        volume = v * count if v is not None and v > 0 else 0.0
    return 4.0 * pi * sphere / (3.0 * volume) if volume > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    ids = range(n)
    props = s.get('element_properties') or {}
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    weights = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    best = [inf] * n
    for b in s.get('neighbors') or []:
        i, j, d = b.get('i'), b.get('j'), b.get('distance_A')
        if i not in ids or j not in ids or d is None or not 0 < d <= 6.000001:
            continue
        ri, rj = radii[i], radii[j]
        if weights[j] > 0 and ri is not None and rj is not None and ri > 0 and rj > 0:
            best[i] = min(best[i], d / (ri + rj))
    total = sum(weights[i] for i in ids if isfinite(best[i]) and best[i] > 0)
    return sum(weights[i] * log(best[i]) for i in ids if isfinite(best[i]) and best[i] > 0) / total if total > 0 else 0.0

