    nearest = [7.0] * n
    for i, j, d in edges:
        if w[j] > 0:
            nearest[i] = min(nearest[i], d)
    count, first, second = [0.0] * n, [0.0] * n, [0.0] * n
    for i, j, d in edges:
        if d <= 1.25 * nearest[i]:
            count[i] += w[j]
            first[i] += w[j] * d
            second[i] += w[j] * d * d
    score, total = 0.0, 0.0
    for i in ids:
        if count[i] > 0 and first[i] > 0:
            mean = first[i] / count[i]
