def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    ids = range(n)
    w = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    elements = [t.get('element') for t in sites]
    counts = {}
    for i in ids:
        counts[elements[i]] = counts.get(elements[i], 0.0) + w[i]
    total = sum(w)
    if total <= 0:
        return 0.0
    expected = 1.0 - sum((v / total) ** 2 for v in counts.values())
    edges = [(b['i'], b['j'], b['distance_A']) for b in (s.get('neighbors') or []) if b.get('i') in ids and b.get('j') in ids and b.get('distance_A') is not None and 0 < b['distance_A'] <= 6.000001]
    nearest = [7.0] * n
    for i, j, d in edges:
        if w[j] > 0:
            nearest[i] = min(nearest[i], d)
    unlike, bonds = 0.0, 0.0
    for i, j, d in edges:
        if d <= 1.25 * nearest[i]:
            weight = w[i] * w[j]
            bonds += weight
            if elements[i] != elements[j]:
                unlike += weight
    return unlike / bonds - expected if bonds > 0 else 0.0

