def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    ids = range(n)
    props = s.get('element_properties') or {}
    chi, hardness = [None] * n, [None] * n
    w = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    for i in ids:
        p = props.get(sites[i].get('element')) or {}
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if ion is not None and affinity is not None and isfinite(ion) and isfinite(affinity) and ion > 0 and ion > affinity:
            chi[i] = 0.5 * (ion + affinity)
            hardness[i] = max(0.1, ion - affinity)
    edges = [(b['i'], b['j'], b['distance_A']) for b in (s.get('neighbors') or []) if b.get('i') in ids and b.get('j') in ids and b.get('distance_A') is not None and 0 < b['distance_A'] <= 6.000001]
    nearest = [7.0] * n
    for i, j, d in edges:
        if w[j] > 0:
            nearest[i] = min(nearest[i], d)
    score = 0.0
    for i, j, d in edges:
        if d <= 1.25 * nearest[i] and chi[i] is not None and chi[j] is not None:
            score += w[i] * w[j] * (chi[i] - chi[j]) ** 2 / ((hardness[i] + hardness[j]) * d)
    total = sum(w)
    return 0.5 * score / total if total > 0 else 0.0

