def feature(s):
    s = s or {}
    lattice = s.get('lattice') or {}
    matrix = lattice.get('matrix')
    if matrix is not None and len(matrix) == 3 and all(row is not None and len(row) == 3 for row in matrix):
        a = np.asarray(matrix)
        if np.all(np.isfinite(a)):
            values = np.linalg.svd(a, compute_uv=False)
            lo, hi = float(np.min(values)), float(np.max(values))
            return log(hi / lo) if lo > 0 and hi > 0 else 0.0
    lengths = lattice.get('lengths_A')
    if lengths is None:
        lengths = [lattice.get('a_A'), lattice.get('b_A'), lattice.get('c_A')]
    valid = [v for v in lengths if v is not None and isfinite(v) and v > 0]
    return log(max(valid) / min(valid)) if len(valid) == 3 else 0.0

